/**
 * Gregorian to Jalali (Shamsi) date converter.
 * Pure JavaScript - no external dependencies needed.
 * Based on the algorithm by Roozbeh Pournader and Mohammad Toossi.
 */

const GREGORIAN_EPOCH = 1721425.5;
const JALALI_EPOCH = 1948320.5;

function mod(a, b) {
  return a - Math.floor(a / b) * b;
}

function div(a, b) {
  return Math.floor(a / b);
}

function leapGregorian(year) {
  return ((year % 4 === 0) && !(year % 100 === 0)) || (year % 400 === 0);
}

function jalCal(jy) {
  const breaks = [
    -61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210,
    1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178,
  ];
  const bl = breaks.length;
  let gy = jy + 621;
  let leapJ = -14;
  let jp = breaks[0];
  let jump = 0;

  if (jy < jp || jy >= breaks[bl - 1]) {
    throw new Error('Invalid Jalali year ' + jy);
  }

  for (let i = 1; i < bl; i += 1) {
    const jm = breaks[i];
    jump = jm - jp;
    if (jy < jm) break;
    leapJ += div(jump, 33) * 8 + div(mod(jump, 33), 4);
    jp = jm;
  }
  let n = jy - jp;
  leapJ += div(n, 33) * 8 + div(mod(n, 33) + 3, 4);
  if (mod(jump, 33) === 4 && jump - n === 4) leapJ += 1;

  const gLeap = leapGregorian(gy);
  const jyStart = gregorianToJd(gy, 3, gLeap ? 20 : 21);
  return { leap: leapJ - 2, gy: gy, marchDay: jyStart };
}

function gregorianToJd(year, month, day) {
  return (
    GREGORIAN_EPOCH - 1 +
    365 * (year - 1) +
    div(year - 1, 4) +
    -div(year - 1, 100) +
    div(year - 1, 400) +
    div(367 * month - 362, 12) +
    (month <= 2 ? 0 : leapGregorian(year) ? -1 : -2) +
    day
  );
}

function jalaliToJd(year, month, day) {
  const cal = jalCal(year);
  return cal.marchDay + (month - 1) * 31 - div(month, 7) * (month - 7) + day - 1;
}

function jdToGregorian(jd) {
  let wjd = Math.floor(jd - 0.5) + 0.5;
  const depoch = wjd - GREGORIAN_EPOCH;
  const quadricent = div(depoch, 146097);
  const dqc = mod(depoch, 146097);
  const cent = div(dqc, 36524);
  const dcent = mod(dqc, 36524);
  const quad = div(dcent, 1461);
  const dquad = mod(dcent, 1461);
  const yindex = div(dquad, 365);
  let year = quadricent * 400 + cent * 100 + quad * 4 + yindex;
  if (!(cent === 4 || yindex === 4)) year += 1;
  const yearday = wjd - gregorianToJd(year, 1, 1);
  const leapadj = wjd < gregorianToJd(year, 3, 1) ? 0 : leapGregorian(year) ? 1 : 2;
  const month = div((yearday + leapadj) * 12 + 373, 367);
  const day = wjd - gregorianToJd(year, month, 1) + 1;
  return { year, month, day };
}

function jdToJalali(jd) {
  const depoch = jd - jalaliToJd(475, 1, 1);
  const cycle = div(depoch, 1029983);
  const cyear = mod(depoch, 1029983);
  let ycycle;
  if (cyear === 1029982) {
    ycycle = 2820;
  } else {
    const aux1 = div(cyear, 366);
    const aux2 = mod(cyear, 366);
    ycycle = div(2134 * aux1 + 2816 * aux2 + 2815, 1028522) + aux1 + 1;
  }
  let year = ycycle + 2820 * cycle + 474;
  if (year <= 0) year -= 1;
  const yday = jd - jalaliToJd(year, 1, 1) + 1;
  const month = yday <= 186 ? Math.ceil(yday / 31) : Math.ceil((yday - 6) / 30);
  const day = jd - jalaliToJd(year, month, 1) + 1;
  return { year, month, day };
}

/**
 * Convert a Gregorian date string (YYYY-MM-DD) to Jalali date string (YYYY/MM/DD).
 * @param {string} gregorianDate - Date string in YYYY-MM-DD format
 * @returns {string} Jalali date in YYYY/MM/DD format, or '—' if invalid
 */
export function toJalali(gregorianDate) {
  if (!gregorianDate) return '—';
  try {
    const parts = gregorianDate.split('-');
    if (parts.length !== 3) return gregorianDate;
    const gy = parseInt(parts[0], 10);
    const gm = parseInt(parts[1], 10);
    const gd = parseInt(parts[2], 10);
    if (isNaN(gy) || isNaN(gm) || isNaN(gd)) return gregorianDate;

    const jd = gregorianToJd(gy, gm, gd);
    const jalali = jdToJalali(jd);
    return `${jalali.year}/${String(jalali.month).padStart(2, '0')}/${String(jalali.day).padStart(2, '0')}`;
  } catch {
    return gregorianDate;
  }
}

/**
 * Convert a Jalali date string (YYYY/MM/DD) to Gregorian date string (YYYY-MM-DD).
 * @param {string} jalaliDate - Date string in YYYY/MM/DD format
 * @returns {string} Gregorian date in YYYY-MM-DD format
 */
export function toGregorian(jalaliDate) {
  if (!jalaliDate) return '';
  try {
    const parts = jalaliDate.split('/');
    if (parts.length !== 3) return jalaliDate;
    const jy = parseInt(parts[0], 10);
    const jm = parseInt(parts[1], 10);
    const jd2 = parseInt(parts[2], 10);
    if (isNaN(jy) || isNaN(jm) || isNaN(jd2)) return jalaliDate;

    const jd = jalaliToJd(jy, jm, jd2);
    const greg = jdToGregorian(jd);
    return `${greg.year}-${String(greg.month).padStart(2, '0')}-${String(greg.day).padStart(2, '0')}`;
  } catch {
    return jalaliDate;
  }
}

/**
 * React component / hook helper: formats a date for display.
 * Returns Jalali formatted date if the input is a Gregorian date string.
 */
export function formatDate(dateStr) {
  return toJalali(dateStr);
}
